export function getLocalTodayDateString(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`; // Пример: "2026-10-19" строго локально
}

export const checkAndResetDailyProgress = () => {
  if (typeof window === 'undefined') return;
  try {
    const todayStr = getLocalTodayDateString();
    const storedDate = localStorage.getItem('app_daily_counter_date') || localStorage.getItem('last_active_date');

    if (storedDate !== todayStr) {
      console.log(`[DailyReset] Наступил новый день (${todayStr}). Предыдущий: ${storedDate}. Сбрасываем счетчик.`);
      localStorage.setItem('app_daily_counter_date', todayStr);
      localStorage.setItem('last_active_date', todayStr);
      localStorage.setItem('daily_learned_count', '0');

      ['DE', 'EN', 'RU'].forEach(lang => {
        try {
          const actKey = `daily_activity_${lang}`;
          const stored = localStorage.getItem(actKey);
          let progress: Record<string, any> = {};
          if (stored) progress = JSON.parse(stored);
          if (progress[todayStr] === undefined) {
            progress[todayStr] = 0;
            localStorage.setItem(actKey, JSON.stringify(progress));
          }
        } catch (e) {}
      });

      resetDayStatsToZero();
      window.dispatchEvent(new Event('storage-update'));
    }
  } catch (err) {
    console.error('Ошибка проверки дневного сброса:', err);
  }
};

function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState(false);
  React.useEffect(() => {
    const check = () => {
      const hasTouch = 'ontouchstart' in window || (typeof navigator !== 'undefined' && navigator.maxTouchPoints > 0);
      const isNarrow = typeof window !== 'undefined' && window.innerWidth < 768;
      setIsMobile(hasTouch || isNarrow);
    };
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);
  return isMobile;
}

function ensureUuid(id?: string): string {
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  if (id && uuidRegex.test(id)) return id;
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

// Client-side image compression for OCR/Groq Vision (1200px max dimension, JPEG 0.72)
async function compressImageForOcr(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = (e) => {
      const img = new window.Image();
      img.src = e.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_DIMENSION = 1200; // Оптимальное разрешение для распознавания текста без перерасхода токенов
        let width = img.width;
        let height = img.height;

        if (width > height) {
          if (width > MAX_DIMENSION) {
            height *= MAX_DIMENSION / width;
            width = MAX_DIMENSION;
          }
        } else {
          if (height > MAX_DIMENSION) {
            width *= MAX_DIMENSION / height;
            height = MAX_DIMENSION;
          }
        }

        canvas.width = Math.round(width);
        canvas.height = Math.round(height);
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);

        // Сжимаем в JPEG с качеством 0.72 — размер падает с 4 МБ до 180-250 КБ
        const compressed = canvas.toDataURL('image/jpeg', 0.72);
        resolve(compressed);
      };
      img.onerror = reject;
    };
    reader.onerror = reject;
  });
}

