// --- AUDIO FEEDBACK ---

const TOCK_B64 = "data:audio/wav;base64,";
const SUCCESS_B64 = "data:audio/wav;base64,";
const FAIL_B64 = "data:audio/wav;base64,";

const audioCache = new Map<string, string>();
const MAX_AUDIO_CACHE_SIZE = 100;
export const setCachedAudioUrl = (key: string, url: string) => {
  if (audioCache.size >= MAX_AUDIO_CACHE_SIZE) {
    const firstKey = audioCache.keys().next().value;
    if (firstKey) {
      const oldUrl = audioCache.get(firstKey);
      if (oldUrl && oldUrl.startsWith('blob:')) {
        try { URL.revokeObjectURL(oldUrl); } catch (e) {}
      }
      audioCache.delete(firstKey);
    }
  }
  audioCache.set(key, url);
};

// ==========================================
// BULLETPROOF NATIVE SOUND ENGINE
// (Web Audio API direct buffers + Instant Oscillator synthesis + Safe Singletons)
// ==========================================

let globalAudioCtx: AudioContext | null = null;
let tockBuffer: AudioBuffer | null = null;
let successBuffer: AudioBuffer | null = null;
let failBuffer: AudioBuffer | null = null;
let isDecodingBuffers = false;
let lastDecodedCtx: AudioContext | null = null;

// Pre-created singletons for HTML5 fallback (strictly 3 elements, NEVER dynamically allocated)
let fallbackTock: HTMLAudioElement | null = null;
let fallbackSuccess: HTMLAudioElement | null = null;
let fallbackFail: HTMLAudioElement | null = null;

function createFallbackAudio(src: string, vol: number): HTMLAudioElement | null {
  if (typeof window === 'undefined') return null;
  try {
    const a = new Audio(src);
    (a as any).playsInline = true;
    a.preload = 'auto';
    a.volume = vol;
    return a;
  } catch (e) {
    return null;
  }
}

let keepAliveSource: AudioBufferSourceNode | null = null;

function ensureAudioKeepAlive(ctx: AudioContext) {
  if (keepAliveSource) return;
  try {
    const silentBuffer = ctx.createBuffer(1, 1, 22050);
    const source = ctx.createBufferSource();
    source.buffer = silentBuffer;
    source.loop = true;
    const gain = ctx.createGain();
    gain.gain.value = 0.0001; // Inaudible, keeps CoreAudio hardware awake in Safari
    source.connect(gain);
    gain.connect(ctx.destination);
    source.start(0);
    keepAliveSource = source;
  } catch (e) {}
}

export const getAudioContext = (): AudioContext | null => {
  if (typeof window === 'undefined') return null;
  const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
  if (!AudioCtx) return null;

  // If context is closed or interrupted by Safari media session, recycle it
  if (!globalAudioCtx || globalAudioCtx.state === 'closed' || (globalAudioCtx.state as any) === 'interrupted') {
    try {
      if (globalAudioCtx) {
        try { globalAudioCtx.close(); } catch (e) {}
      }
      globalAudioCtx = new AudioCtx();
      lastDecodedCtx = null;
      tockBuffer = null;
      successBuffer = null;
      failBuffer = null;
      keepAliveSource = null;
    } catch (e) {
      return null;
    }
  }

  if (globalAudioCtx.state === 'suspended') {
    globalAudioCtx.resume().catch(() => {});
  }

  ensureAudioKeepAlive(globalAudioCtx);

  return globalAudioCtx;
};

// Pure Web Audio API synthesizers — zero external files, zero latency, impossible to fail in WebKit/Safari
function synthesizeTock(ctx: AudioContext, volume: number = 0.3) {
  try {
    if (ctx.state !== 'running') {
      ctx.resume().catch(() => {});
    }
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const now = Math.max(ctx.currentTime, 0.001) + 0.002;
    osc.type = 'sine';
    osc.frequency.setValueAtTime(1400, now);
    osc.frequency.setTargetAtTime(180, now, 0.007);
    gain.gain.setValueAtTime(volume * 0.7, now);
    gain.gain.setTargetAtTime(0.0001, now, 0.007);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.04);
  } catch (e) {}
}

function synthesizeSuccess(ctx: AudioContext, volume: number = 0.4) {
  try {
    if (ctx.state !== 'running') {
      ctx.resume().catch(() => {});
    }
    const now = Math.max(ctx.currentTime, 0.001) + 0.002;
    [
      { freq: 523.25, start: 0, dur: 0.22, vol: volume * 0.6 },
      { freq: 783.99, start: 0.07, dur: 0.28, vol: volume * 0.75 },
    ].forEach(({ freq, start, dur, vol }) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, now + start);
      gain.gain.setValueAtTime(0.001, now + start);
      gain.gain.linearRampToValueAtTime(vol, now + start + 0.015);
      gain.gain.setTargetAtTime(0.0001, now + start + 0.02, dur * 0.35);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now + start);
      osc.stop(now + start + dur + 0.03);
    });
  } catch (e) {}
}

function synthesizeFail(ctx: AudioContext, volume: number = 0.4) {
  try {
    if (ctx.state !== 'running') {
      ctx.resume().catch(() => {});
    }
    const now = Math.max(ctx.currentTime, 0.001) + 0.002;
    [
      { freq: 220, start: 0, dur: 0.12, vol: volume * 0.5 },
      { freq: 164.81, start: 0.07, dur: 0.2, vol: volume * 0.6 },
    ].forEach(({ freq, start, dur, vol }) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, now + start);
      gain.gain.setValueAtTime(0.001, now + start);
      gain.gain.linearRampToValueAtTime(vol, now + start + 0.01);
      gain.gain.setTargetAtTime(0.0001, now + start + 0.02, dur * 0.3);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now + start);
      osc.stop(now + start + dur + 0.03);
    });
  } catch (e) {}
}

// Safe base64 -> ArrayBuffer -> AudioBuffer decode supporting all browser versions
function decodeBase64Audio(ctx: AudioContext, base64: string): Promise<AudioBuffer | null> {
  return new Promise((resolve) => {
    try {
      const clean = base64.replace(/^data:audio\/\w+;base64,/, '');
      const binaryString = window.atob(clean);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      const arrayBuf = bytes.buffer.slice(0);
      
      const successCb = (buf: AudioBuffer) => resolve(buf);
      const errorCb = () => resolve(null);

      const res = ctx.decodeAudioData(arrayBuf, successCb, errorCb);
      if (res && typeof (res as any).then === 'function') {
        (res as any).then(successCb).catch(errorCb);
      }
    } catch (e) {
      resolve(null);
    }
  });
}

export async function loadAudioBuffers() {
  if (typeof window === 'undefined' || isDecodingBuffers) return;
  const ctx = getAudioContext();
  if (!ctx) return;

  if (lastDecodedCtx !== ctx) {
    tockBuffer = null;
    successBuffer = null;
    failBuffer = null;
    lastDecodedCtx = ctx;
  }

  isDecodingBuffers = true;
  try {
    if (!tockBuffer) {
      tockBuffer = await decodeBase64Audio(ctx, TOCK_B64);
    }
    if (!successBuffer) {
      successBuffer = await decodeBase64Audio(ctx, SUCCESS_B64);
    }
    if (!failBuffer) {
      failBuffer = await decodeBase64Audio(ctx, FAIL_B64);
    }
  } catch (e) {
  } finally {
    isDecodingBuffers = false;
  }
}

function playBufferDirect(buffer: AudioBuffer | null, volume: number): boolean {
  const ctx = getAudioContext();
  if (!ctx || !buffer) return false;

  try {
    if (ctx.state !== 'running') {
      ctx.resume().catch(() => {});
    }
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    const gainNode = ctx.createGain();
    const now = Math.max(ctx.currentTime, 0.001) + 0.001;
    gainNode.gain.setValueAtTime(volume, now);
    source.connect(gainNode);
    gainNode.connect(ctx.destination);
    source.start(now);
    return true;
  } catch (e) {
    return false;
  }
}

function playFallback(type: 'tock' | 'success' | 'fail', volume: number) {
  if (typeof window === 'undefined') return;
  try {
    let el: HTMLAudioElement | null = null;
    if (type === 'tock') {
      if (!fallbackTock) fallbackTock = createFallbackAudio(TOCK_B64, volume);
      el = fallbackTock;
    } else if (type === 'success') {
      if (!fallbackSuccess) fallbackSuccess = createFallbackAudio(SUCCESS_B64, volume);
      el = fallbackSuccess;
    } else {
      if (!fallbackFail) fallbackFail = createFallbackAudio(FAIL_B64, volume);
      el = fallbackFail;
    }
    if (el) {
      el.volume = volume;
      el.currentTime = 0;
      const p = el.play();
      if (p !== undefined) p.catch(() => {});
    }
  } catch (e) {}
}

export const playTockSound = () => {
  const ctx = getAudioContext();
  if (ctx) {
    if (ctx.state !== 'running') {
      ctx.resume().catch(() => {});
    }
    const played = tockBuffer ? playBufferDirect(tockBuffer, 0.3) : false;
    if (!played) {
      synthesizeTock(ctx, 0.3);
      loadAudioBuffers();
    }
    return;
  }
  playFallback('tock', 0.3);
};

export const playFeedbackSound = (isCorrect: boolean) => {
  const ctx = getAudioContext();
  const buffer = isCorrect ? successBuffer : failBuffer;
  const vol = 0.4;
  if (ctx) {
    if (ctx.state !== 'running') {
      ctx.resume().catch(() => {});
    }
    const played = buffer ? playBufferDirect(buffer, vol) : false;
    if (!played) {
      if (isCorrect) synthesizeSuccess(ctx, vol);
      else synthesizeFail(ctx, vol);
      loadAudioBuffers();
    }
    return;
  }
  playFallback(isCorrect ? 'success' : 'fail', vol);
};

export const initAudioCtx = async () => {
  if (typeof window === 'undefined') return;
  const ctx = getAudioContext();
  if (ctx && ctx.state !== 'running') {
    await ctx.resume().catch(() => {});
  }
  loadAudioBuffers();
};

export const getUiSounds = () => {
  if (typeof window === 'undefined') return null;
  return {
    tock: { play: () => playTockSound() },
    success: { play: () => playFeedbackSound(true) },
    fail: { play: () => playFeedbackSound(false) },
  };
};

