function HeaderWidgets({ activeBook, onBack, onReviewMistakes }: { activeBook?: BookMeta | null, onBack?: () => void, onReviewMistakes?: () => void }) {
  const [adminOpen, setAdminOpen] = useState(false);
  const [isLangOpen, setIsLangOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const [isStatsOpen, setIsStatsOpen] = useState(false);
  const langRef = useRef<HTMLDivElement>(null);
  const { appLanguage, setAppLanguage } = useStore();
  const effectiveLang = normalizeLanguage(activeBook?.language || appLanguage || 'DE');
  const { stats } = useDayStats({ language: effectiveLang });

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 12);
    };
    handleScroll();
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const [isDark, setIsDark] = useState(false);
  useEffect(() => {
    setIsDark(document.documentElement.classList.contains('dark'));
  }, []);

  const toggleTheme = () => {
    const next = !isDark;
    setIsDark(next);
    if (next) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (langRef.current && !langRef.current.contains(e.target as Node)) {
        setIsLangOpen(false);
      }
    };
    if (isLangOpen) {
      document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isLangOpen]);

  const [dailyLearnedCount, setDailyLearnedCount] = useState<number>(0);
  const [daily, setDaily] = useState<Record<string, any>>({});

  const checkAndResetDaily = useCallback(() => {
    try {
      const todayStr = getLocalTodayDateString();
      const storedDate = localStorage.getItem('app_daily_counter_date') || localStorage.getItem('last_active_date');

      if (storedDate !== todayStr) {
        console.log(`[DailyReset] Наступил новый день (${todayStr}). Предыдущий: ${storedDate}. Сбрасываем счетчик.`);
        localStorage.setItem('app_daily_counter_date', todayStr);
        localStorage.setItem('last_active_date', todayStr);
        localStorage.setItem('daily_learned_count', '0');
        setDailyLearnedCount(0);
      } else {
        const savedCount = parseInt(localStorage.getItem('daily_learned_count') || '0', 10) || 0;
        setDailyLearnedCount(savedCount);
      }
    } catch (err) {
      console.error('Ошибка проверки дневного сброса:', err);
    }
  }, []);

  useEffect(() => {
    checkAndResetDaily();

    // Сброс при возвращении на вкладку (если вкладка висела открытой ночью)
    const handleVisibility = () => {
      if (document.visibilityState === 'visible') {
        checkAndResetDaily();
      }
    };

    window.addEventListener('focus', checkAndResetDaily);
    document.addEventListener('visibilitychange', handleVisibility);

    const loadProgress = () => {
      checkAndResetDaily();
      try {
        const stored = localStorage.getItem(`daily_activity_${appLanguage}`);
        if (stored) setDaily(JSON.parse(stored));
        else setDaily({});
      } catch (e) {}
    };
    loadProgress();
    window.addEventListener('storage-update', loadProgress);

    return () => {
      window.removeEventListener('focus', checkAndResetDaily);
      document.removeEventListener('visibilitychange', handleVisibility);
      window.removeEventListener('storage-update', loadProgress);
    };
  }, [appLanguage, checkAndResetDaily]);

  const todayStr = getLocalTodayDateString();
  const rawCount = daily[todayStr];
  const todayCount = typeof rawCount === 'number' ? rawCount : (rawCount?.total || (typeof rawCount === 'string' ? parseInt(rawCount) || 0 : 0));
  const realCardsCount = getTodayCompletedCardsCount(effectiveLang);
  const statsCardsDone = stats?.date === todayStr && typeof stats?.cardsDone === 'number' ? stats.cardsDone : 0;
  const displayTodayCount = Math.max(statsCardsDone, realCardsCount, todayCount, dailyLearnedCount);

  const currentLang = LANGUAGES.find(l => l.code === appLanguage) || LANGUAGES[0];
  const currentTranslations = UI_TRANSLATIONS[appLanguage] || UI_TRANSLATIONS.DE;

  return (
    <>
      <AnimatePresence>
        {adminOpen && <AdminModal onClose={() => setAdminOpen(false)} activeBook={activeBook} />}
      </AnimatePresence>

      <header 
        className={cn(
          "sticky top-0 z-50 w-full select-none transition-all duration-300",
          isScrolled 
            ? "bg-white/80 dark:bg-black/75 backdrop-blur-xl border-b border-black/[0.06] dark:border-white/10 shadow-sm" 
            : "bg-transparent border-b border-transparent"
        )}
      >
        <div className="w-full max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          
          {/* 1. ЛЕВЫЙ УГОЛ: ЯЗЫКОВАЯ ПИЛЮЛЯ / BACK PILL */}
          <div className="flex items-center">
            {activeBook ? (
              <button
                onClick={onBack}
                className="h-9 px-3.5 rounded-full bg-white dark:bg-[#1C1C1E] hover:bg-zinc-50 dark:hover:bg-[#2C2C2E] border border-zinc-200/80 dark:border-white/15 shadow-sm text-zinc-900 dark:text-white text-sm font-medium flex items-center gap-2 transition-all active:scale-95 cursor-pointer select-none transform-gpu"
                title="Zurück zur Übersicht"
              >
                <ArrowLeft className="w-3.5 h-3.5 text-zinc-500 dark:text-zinc-400" />
                <span className="truncate max-w-[130px] sm:max-w-[200px]">{activeBook.title}</span>
              </button>
            ) : (
              <div ref={langRef} className="relative">
                <button
                  type="button"
                  onClick={() => setIsLangOpen(prev => !prev)}
                  className="h-9 px-3 rounded-full flex items-center gap-2 bg-white dark:bg-[#1C1C1E] border border-zinc-200/80 dark:border-white/15 shadow-sm text-zinc-900 dark:text-white hover:bg-zinc-50 dark:hover:bg-[#2C2C2E] transition-all duration-150 active:scale-95 cursor-pointer select-none transform-gpu"
                  title="Sprache wählen"
                >
                  <span className="text-base leading-none select-none">{currentLang.flag}</span>
                  <span className="font-bold text-xs tracking-tight text-zinc-900 dark:text-white">{appLanguage}</span>
                  <ChevronDown className={cn("w-3 h-3 text-zinc-500 dark:text-zinc-400 transition-transform duration-200", isLangOpen && "rotate-180")} />
                </button>

                <AnimatePresence>
                  {isLangOpen && (
                    <motion.div
                      initial={{ opacity: 0, scale: 0.95, y: -4 }}
                      animate={{ opacity: 1, scale: 1, y: 0 }}
                      exit={{ opacity: 0, scale: 0.95, y: -4 }}
                      transition={{ duration: 0.15, ease: "easeOut" }}
                      className="absolute left-0 top-full mt-2 w-36 rounded-xl p-1 bg-white dark:bg-[#1C1C1E] shadow-xl border border-zinc-200/80 dark:border-white/15 z-50 flex flex-col gap-0.5 select-none"
                    >
                      {LANGUAGES.map(lang => {
                        const isSelected = appLanguage === lang.code;
                        return (
                          <button
                            key={lang.code}
                            type="button"
                            onClick={() => {
                              setAppLanguage(lang.code as any);
                              setIsLangOpen(false);
                            }}
                            className={cn(
                              "w-full px-2.5 py-1.5 rounded-lg flex items-center justify-between text-xs transition-colors cursor-pointer",
                              isSelected
                                ? "bg-black/5 dark:bg-white/10 text-zinc-900 dark:text-white font-semibold"
                                : "text-zinc-600 dark:text-zinc-400 hover:bg-black/5 dark:hover:bg-white/5 hover:text-zinc-900 dark:hover:text-zinc-200"
                            )}
                          >
                            <div className="flex items-center gap-2">
                              <span className="text-sm">{lang.flag}</span>
                              <span>{lang.label}</span>
                            </div>
                            {isSelected && <Check className="w-3.5 h-3.5 text-zinc-700 dark:text-zinc-300" />}
                          </button>
                        );
                      })}
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            )}
          </div>

          {/* 2. ПРАВЫЙ УГОЛ: НАВИГАЦИОННАЯ ПАНЕЛЬ APPLE */}
          <div className="flex items-center gap-2">
            {/* Капсула счетчика */}
            <button 
              type="button"
              onClick={(e) => { 
                if (e.detail === 3) {
                  setAdminOpen(true);
                } else {
                  setIsStatsOpen(true);
                }
              }}
              className="h-9 px-3.5 rounded-full bg-white/80 dark:bg-zinc-900/80 hover:bg-white dark:hover:bg-zinc-800/90 border border-black/[0.08] dark:border-white/10 backdrop-blur-xl transition-all duration-200 active:scale-95 flex items-center gap-2 shadow-sm dark:shadow-lg text-zinc-800 dark:text-zinc-200 cursor-pointer"
              title="Статистика дня"
            >
              <svg className="w-3.5 h-3.5 text-zinc-500 dark:text-zinc-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="m12 3-9 5 9 5 9-5-9-5z" />
                <path d="m3 12 9 5 9-5" />
                <path d="m3 17 9 5 9-5" />
              </svg>
              <span suppressHydrationWarning className="text-xs font-semibold tabular-nums tracking-tight font-sans">
                {displayTodayCount} <span className="text-zinc-400 dark:text-zinc-500 font-normal">/ 200</span>
              </span>
            </button>

            {/* Кнопка переключения темы */}
            <button 
              type="button"
              onClick={toggleTheme}
              className="w-9 h-9 rounded-full bg-white/80 dark:bg-zinc-900/80 hover:bg-white dark:hover:bg-zinc-800/90 border border-black/[0.08] dark:border-white/10 backdrop-blur-xl flex items-center justify-center text-zinc-600 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-white transition shadow-sm active:scale-95 cursor-pointer"
              aria-label="Toggle theme"
              title={isDark ? "Heller Modus" : "Dunkler Modus"}
            >
              {isDark ? <Moon className="w-3.5 h-3.5" /> : <Sun className="w-3.5 h-3.5" />}
            </button>
          </div>

        </div>
      </header>

      <StatsPopover
        isOpen={isStatsOpen}
        onClose={() => setIsStatsOpen(false)}
        stats={stats}
        language={effectiveLang}
        onReviewMistakes={() => {
          setIsStatsOpen(false);
          if (onReviewMistakes) onReviewMistakes();
        }}
      />
    </>
  );
}



interface ModeBadgeInfo {
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  iconColor: string;
}

function getBookModeBadge(book: BookMeta): ModeBadgeInfo | null {
  const mode = book.training_mode;
  const isFlashcardCategory = book.category === 'flashcards';

  if (mode === 'rapid_flashcards' || isFlashcardCategory) {
    return {
      label: 'BLITZKARTEN',
      icon: Layers,
      iconColor: 'text-amber-400',
    };
  }

  if (mode === 'redemittel') {
    return {
      label: 'REDEMITTEL',
      icon: Shuffle,
      iconColor: 'text-sky-400',
    };
  }

  if (mode === 'starke_verben') {
    return {
      label: 'STARKE VERBEN',
      icon: Flame,
      iconColor: 'text-rose-400',
    };
  }

  if (mode === 'preposition_drill') {
    return {
      label: 'PRÄPOSITIONEN',
      icon: Database,
      iconColor: 'text-purple-400',
    };
  }

  return null;
}

